tags["Armazenagem"] = model.layers["Armazenagem"] || model.layers.add("Armazenagem")
tags["NR-06 EPI"] = model.layers["NR-06 EPI"] || model.layers.add("NR-06 EPI")
def caixa(ents, nome, mat, tag, x, y, z, dx, dy, dz)
  g = ents.add_group
  pts = [[x, y, z], [x + dx, y, z], [x + dx, y + dy, z], [x, y + dy, z]].map { |p| Geom::Point3d.new(p.map { |v| v.m }) }
  f = g.entities.add_face(pts)
  f.reverse! if f.normal.z < 0
  f.pushpull(dz.m)
  g.name = nome
  g.material = mat
  g.layer = tag
  g
end
